// Analyse-workflow: leest de multipart-upload en bouwt per document een
// Docling-item (base64). Elk document krijgt een docType-label
// (bank / kadaster / overig) op basis van de bestandsnaam; alle documenten
// gaan door naar de juridische analyse.

const webhookItem = $input.first();
const b = (webhookItem && webhookItem.binary) || {};
const keys = Object.keys(b);

// Deze workflow kent maar één flow; 'mode' blijft in de items staan omdat
// downstream-nodes (Extract Markdown, specialist-prompts) het veld doorgeven.
const mode = 'analyse';

if (keys.length === 0) {
  throw new Error(
    'Webhook ontving geen binary bestanden. Stuur PDF- of Word-bestanden (.docx) als multipart/form-data mee.'
  );
}

function isConvertibleDoc(k) {
  const fn = String(b[k]?.fileName || '').toLowerCase();
  const mime = String(b[k]?.mimeType || '').toLowerCase();
  if (fn.endsWith('.pdf') || mime.includes('pdf')) return true;
  if (fn.endsWith('.docx')) return true;
  if (mime.includes('wordprocessingml') || mime.includes('officedocument.wordprocessingml')) return true;
  return false;
}

const docKeys = keys.filter(isConvertibleDoc);
if (docKeys.length === 0) {
  throw new Error(
    'Geen ondersteunde documenten (PDF of .docx) in de upload.'
  );
}

async function loadAsBase64(binaryKey) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  return buffer.toString('base64');
}

const base = {
  receivedAt: new Date().toISOString(),
  mode,
};

const BANK_RX_LEGACY = /passeer|nti|rabobank|abnamro|abn[\s_-]?amro|ing|obvion|munt|bank|stater/;
const KAD_RX_LEGACY = /eigendom|kadaster/;

function bankScore(fname) {
  const f = String(fname || '').toLowerCase();
  if (
    /passeerbevestig|passeergegevens|gelden\s+notaris|conceptnota|factuur|\bwwft\b|bankpas|definitieve\s+set|uitbetaling/i.test(f)
  ) {
    return -100;
  }
  let s = 0;
  if (/passeeropdracht/i.test(f)) s += 200;
  if (/notarisinstructie|voorlopige\s+gegevens/i.test(f)) s += 180;
  if (/rabobank|co[oö]peratieve\s+rabo|abn|abnamro|\bing\b|obvion|regiobank|florius|aegon|asr/i.test(f)) s += 85;
  if (/\bnti\b|nutsworth|stater/i.test(f)) s += 85;
  if (/\bpasseer\b/i.test(f) && !/bevestig|melding|gegevens/i.test(f)) s += 35;
  if (/voorlopig/i.test(f)) s -= 40;
  return s;
}

function isKadasterName(fname) {
  const f = String(fname || '').toLowerCase();
  if (/passeeropdracht|notarisinstructie/i.test(f)) return false;
  if (/passeerbevestig|\bwwft\b|\bfactuur\b|bankpas|uitbetaling|\.eml|conceptnota|nota\s+-/i.test(f)) {
    return false;
  }
  return /kadastraal|hypothecair|eigendom|kadaster|objectlijst|rechthebbende|brondocument|uittreksel|kadastrale\s+kaart|hypotheekakte|\bkik\b|\bhyp\d|onroerende\s+zaken|perceel/i.test(f);
}

const items = [];
for (const k of docKeys) {
  const fname = String(b[k]?.fileName || '').toLowerCase();
  let docType = 'overig';
  if (bankScore(fname) >= 50) docType = 'bank';
  else if (isKadasterName(fname) || KAD_RX_LEGACY.test(fname)) docType = 'kadaster';
  const blob = await loadAsBase64.call(this, k);
  items.push({
    json: {
      ...base,
      docType,
      filename: b[k]?.fileName || `${k}.pdf`,
      base64_string: blob,
    },
  });
}
return items;

// Per Docling-response: pak de markdown en bewaar docType + mode + bestandsnaam.
const sourceItem = $('Split Input Files').itemMatching($itemIndex);
const docType = sourceItem?.json?.docType || $json.docType || 'overig';
const mode = sourceItem?.json?.mode || 'akte';
const filename = sourceItem?.json?.filename || '';

const payload = $json;
let md = '';
if (payload?.document?.md_content) md = payload.document.md_content;
else if (payload?.md_content) md = payload.md_content;
else if (payload?.result?.document?.md_content) md = payload.result.document.md_content;
else if (Array.isArray(payload?.documents) && payload.documents[0]?.md_content) md = payload.documents[0].md_content;

if (!md) {
  throw new Error(`Docling gaf geen md_content terug voor ${filename || docType}. Top-level keys: ${Object.keys(payload || {}).join(', ')}`);
}

// Strip ingesloten afbeeldingen. Docling sluit soms volledige bitmaps als
// base64 data-URI in de markdown in (bv. een BRP-uitdraai met logo/foto).
// Die ruis vult de LLM-context (gemeten tot 70%+ van de prompt) en doet het
// model onzin/gibberish produceren. We verwijderen de beelddata; de
// leesbare tekst blijft volledig intact.
function stripEmbeddedImages(text) {
  let t = String(text || '');
  // Markdown-afbeelding met data-URI: ![alt](data:image/png;base64,....)
  t = t.replace(/!\[[^\]]*\]\(\s*data:[^)]*\)/gi, '');
  // HTML <img src="data:...">
  t = t.replace(/<img[^>]*src=["']?data:[^>]*>/gi, '');
  // Vangnet: overgebleven kale data-URI's (contigue base64-reeks).
  t = t.replace(/data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]+/gi, '');
  // Opruimen: 3+ opeenvolgende lege regels terugbrengen naar 1 lege regel.
  t = t.replace(/\n{3,}/g, '\n\n');
  return t.trim();
}

md = stripEmbeddedImages(md);

return { json: { docType, mode, filename, markdown: md } };

// Analyse-flow (mode='analyse'): voegt alle aangeleverde markdowns samen tot
// één blok dat als één prompt aan de juridische-analyse-LLM gestuurd kan
// worden. Werkt voor 1..N PDFs.
const items = $input.all();
if (!items.length) {
  throw new Error('Geen markdowns ontvangen voor de analyse-flow.');
}

const MAX_PER_DOC = 12000;
function clamp(s, max) {
  const txt = String(s || '');
  if (txt.length <= max) return txt;
  return txt.slice(0, max) + '\n…[afgekapt voor analyse-prompt]';
}

function docTypeLabel(t) {
  if (t === 'bank') return 'Bank-passeeropdracht';
  if (t === 'kadaster') return 'Kadaster eigendomsinformatie';
  return 'Document';
}

const docs = items.map((it, i) => {
  const j = it.json || {};
  return {
    index: i + 1,
    docType: j.docType || 'overig',
    filename: j.filename || `document_${i + 1}.pdf`,
    markdown: clamp(j.markdown || '', MAX_PER_DOC)
  };
});

const klantNaam = '';
const now = new Date();
const zaaknummer = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}${String(now.getSeconds()).padStart(2, '0')}`;

const bankDocs = docs.filter((d) => d.docType === 'bank').map((d) => d.filename);
const bankDisplay = bankDocs.length
  ? `Onbekend (uit ${bankDocs.join(', ')})`
  : 'Onbekend';

return [{
  json: {
    mode: 'analyse',
    docs,
    documentCount: docs.length,
    zaaknummer,
    bankDisplayName: bankDisplay,
    klantSamenvatting: klantNaam
  }
}];

// Structured-extractie voor de Object&partijen-specialist (mode=analyse).
// Haalt uit de ruwe markdown van bank + kadaster de minimale gestructureerde
// data (klanten/onderpand/kadastrale aanduiding) die de deterministische
// mismatch-checks nodig hebben. De analyse-flow kent zelf geen extractie.
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';
let registry;
try { registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8')); }
catch (err) { throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`); }

const tmpl = String(registry.partijen_extraction_prompt || '');
if (!tmpl) throw new Error('registry.json mist partijen_extraction_prompt.');

const limits = registry.context_limits || {};
const MAX = Number(limits.specialist_partijen_analyse_combined) || 26000;
function clamp(s, max) {
  const t = String(s || '');
  return t.length <= max ? t : t.slice(0, max) + '\n…[afgekapt voor partijen-extractie]';
}

const agg = $('Aggregate Markdowns').first()?.json || {};
const docs = Array.isArray(agg.docs) ? agg.docs : [];
const bankMd = docs.filter((d) => d.docType === 'bank').map((d) => d.markdown || '').join('\n\n');
const kadMd = docs.filter((d) => d.docType === 'kadaster').map((d) => d.markdown || '').join('\n\n');
const hasBoth = Boolean(bankMd) && Boolean(kadMd);

const chatInput = hasBoth
  ? tmpl.split('{{bank_markdown}}').join(clamp(bankMd, MAX)).split('{{kadaster_markdown}}').join(clamp(kadMd, MAX))
  : 'Geen bank- én kadasterdocument beschikbaar om te vergelijken. Geef ALLEEN deze JSON terug:\n{"bank_klanten": [], "onderpand_straat": "", "onderpand_woonplaats": "", "kadaster_klanten": [], "kadastrale_gemeente": "", "kadastrale_sectie": "", "kadastrale_nummer": ""}';

return { json: { chatInput, has_both: hasBoth } };

// Parseert de structured-extractie voor de Object&partijen-specialist tot
// { partijen_extracted: {bank_klanten[], kadaster_klanten[], onderpand_*, kadastrale_*} }.
// LET OP: een Ollama-model met format:json levert de JSON vaak als top-level
// velden op het item (niet als string onder .text). Daarom valt de parser
// terug op de eigen keys van het node als er geen tekststring is.
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  return t.trim();
}
function tryParse(node) {
  const raw = extractText(node).trim();
  if (raw) {
    try { return JSON.parse(unwrapJsonLike(raw)); } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch {} }
  }
  // Fallback: JSON zit al als top-level velden op het item (format:json).
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys(node || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = node[k];
  }
  return obj;
}
function arr(x) { return Array.isArray(x) ? x : []; }
// Schoont een naam: strip alles vanaf een komma of ' geboren' (geboortedatum-
// ruis), en veelvoorkomende aanhef, zodat de achternaam-vergelijking klopt.
function cleanName(s) {
  return String((s && (s.naam ?? s)) || '')
    .split(/,| geboren /i)[0]
    .replace(/\b(mevrouw|mevr|de\s+heer|dhr|mw|hr)\b\.?/gi, '')
    .replace(/^[\s.,;-]+/, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const node = $input.all()[0]?.json || {};
let p = tryParse(node);
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};

const extracted = {
  bank_klanten: arr(p.bank_klanten).map((k) => ({ naam: cleanName(k) })).filter((k) => k.naam),
  kadaster_klanten: arr(p.kadaster_klanten).map((k) => ({ naam: cleanName(k) })).filter((k) => k.naam),
  onderpand_straat: String(p.onderpand_straat || ''),
  onderpand_woonplaats: String(p.onderpand_woonplaats || ''),
  kadastrale_gemeente: String(p.kadastrale_gemeente || ''),
  kadastrale_sectie: String(p.kadastrale_sectie || ''),
  kadastrale_nummer: String(p.kadastrale_nummer || ''),
};
return [{ json: { partijen_extracted: extracted } }];

// Vererving-specialist. Draait in mode='analyse'; input via $('Aggregate Markdowns').docs[].
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';

const mode = String($('Split Input Files').first()?.json?.mode || '').trim().toLowerCase();

let registry;
try {
  registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
} catch (err) {
  throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`);
}

const tmpl = String(registry.legal_specialist_prompts?.vererving || '');
if (!tmpl) {
  throw new Error('registry.json mist legal_specialist_prompts.vererving.');
}

function clamp(s, max) {
  const txt = String(s || '');
  if (txt.length <= max) return txt;
  return txt.slice(0, max) + '\n…[afgekapt voor vererving-prompt]';
}

const limits = (registry.context_limits || {});
const MAX_MD = Number(limits.specialist_vererving) || 14000;

let kadMdFull = '';
let metaForward = {};
const aggItem = $('Aggregate Markdowns').first()?.json || {};
const docs = Array.isArray(aggItem.docs) ? aggItem.docs : [];
kadMdFull = docs.map((d, i) => {
  const label = d.docType === 'bank' ? 'Bank-passeeropdracht'
    : d.docType === 'kadaster' ? 'Kadaster eigendomsinformatie'
    : 'Overig dossier-stuk';
  return `=== DOCUMENT ${i + 1} — ${label} — ${d.filename || `document_${i + 1}`} ===\n${d.markdown || ''}`;
}).join('\n\n');
metaForward = {
  bankDisplayName: aggItem.bankDisplayName || '',
  zaaknummer: aggItem.zaaknummer || '',
};

const kadMd = clamp(kadMdFull, MAX_MD);

const PATTERNS = [
  /(?:^|\b)overled(?:en|\.)/i,
  // BRP gebruikt het zelfstandig naamwoord "Overlijden" (bv. "Reden
  // ontbinding: Overlijden echtgenoot/geregistreerd partner") — dat moet
  // óók de erfrecht-specialist triggeren, niet alleen de werkwoordsvorm.
  /overlijden/i,
  /reden\s+ontbinding[^\n]*overl(?:ijden|eden)/i,
  /†/,
  /verklaring\s+van\s+erfrecht/i,
  /akte\s+van\s+verdeling/i,
  /\b(?:weduwe|weduwnaar)\b/i,
  /onverdeelde\s+nalatenschap/i,
  /(?:sterfdatum|datum\s+van\s+overlijden)/i,
  /wettelijke\s+verdeling/i,
  /(?:saisine|art\.?\s*4:182)/i,
];

const hits = [];
for (const re of PATTERNS) {
  const m = kadMdFull.match(re);
  if (m) hits.push(m[0]);
}
const signalCount = hits.length;

let chatInput;
if (signalCount > 0) {
  chatInput = tmpl.split('{{kadaster_markdown}}').join(kadMd);
} else {
  chatInput = 'Het bijgevoegde kadasterfragment bevat geen indicaties van vererving, overlijden, verklaring van erfrecht of een onverdeelde nalatenschap. Geef ALLEEN deze JSON terug, niets anders:\n{"aandachtspunten": []}';
}

return {
  json: {
    chatInput,
    signal_count: signalCount,
    signal_hits: hits.slice(0, 5),
    mode,
    ...metaForward,
  }
};

// Parseert de output van de Vererving-specialist. Werkt zowel met geldige
// JSON via format=json als met tekst inclusief eventuele markdown-fences.
// Forceert categorie='Vererving' (specialist mag dat veld niet veranderen)
// en bronnen=['kadaster'].
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) {
    t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  }
  return t.trim();
}
function parseSpec(node) {
  const raw = extractText(node).trim();
  if (raw) {
    try { return JSON.parse(unwrapJsonLike(raw)); } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) {
      try { return JSON.parse(m[0]); } catch {}
    }
  }
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys(node || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = node[k];
  }
  return obj;
}

const all = $input.all();
const node = all[0]?.json || {};

// Korte-circuit: als het voorfilter geen vererving-signalen vond, vertrouwen
// we de LLM-output niet en geven we direct een lege array terug. Dit elimineert
// false positives van een 3B-model op kadaster-teksten zonder vererving.
let signalCount = -1;
try {
  const meta = $('Build Vererving Prompt').first()?.json;
  if (typeof meta?.signal_count === 'number') signalCount = meta.signal_count;
} catch (_) {}

if (signalCount === 0) {
  return [{ json: { vererving_aandachtspunten: [], signal_count: 0 } }];
}

let parsed = parseSpec(node);

if (!parsed || typeof parsed !== 'object') {
  parsed = { aandachtspunten: [] };
}

const WRAPPER_KEYS = new Set(['analyse', 'analysis', 'data', 'response', 'result', 'output', 'vererving']);
let depth = 0;
while (
  parsed && typeof parsed === 'object' && !Array.isArray(parsed) &&
  Object.keys(parsed).length === 1 &&
  WRAPPER_KEYS.has(Object.keys(parsed)[0]) && depth < 3
) {
  parsed = parsed[Object.keys(parsed)[0]];
  depth++;
}

const aandacht = Array.isArray(parsed.aandachtspunten) ? parsed.aandachtspunten : [];
const MAX_ITEMS = 4;
const normalised = aandacht.slice(0, MAX_ITEMS).map((ap, i) => {
  const e = String(ap?.ernst || '').trim().toLowerCase();
  const ALLOWED = new Set(['kritiek', 'aandacht', 'info']);
  const ALIASES = { critical: 'kritiek', blokkerend: 'kritiek', warning: 'aandacht', warn: 'aandacht', notice: 'info', informatief: 'info' };
  const ernst = ALLOWED.has(e) ? e : (ALIASES[e] || 'aandacht');
  const idRaw = String(ap?.id || '').trim();
  const id = idRaw
    ? (idRaw.startsWith('vererving-') ? idRaw : `vererving-${idRaw}`)
    : `vererving-${i + 1}`;
  return {
    id,
    ernst,
    categorie: 'Vererving',
    titel: String(ap?.titel || '').slice(0, 160),
    constatering: String(ap?.constatering || ''),
    juridisch_kader: String(ap?.juridisch_kader || ''),
    actie: String(ap?.actie || ''),
    bronnen: ['kadaster']
  };
});

return [{ json: { vererving_aandachtspunten: normalised, signal_count: signalCount } }];

// Lasten-specialist. Draait in mode='analyse'; input via $('Aggregate Markdowns').docs[].
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';

const mode = String($('Split Input Files').first()?.json?.mode || '').trim().toLowerCase();

let registry;
try {
  registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
} catch (err) {
  throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`);
}

const tmpl = String(registry.legal_specialist_prompts?.lasten || '');
if (!tmpl) {
  throw new Error('registry.json mist legal_specialist_prompts.lasten.');
}

function clamp(s, max) {
  const txt = String(s || '');
  if (txt.length <= max) return txt;
  return txt.slice(0, max) + '\n…[afgekapt voor lasten-prompt]';
}

const limits = (registry.context_limits || {});
const MAX_MD = Number(limits.specialist_lasten) || 14000;

let kadMdFull = '';
let metaForward = {};
const aggItem = $('Aggregate Markdowns').first()?.json || {};
const docs = Array.isArray(aggItem.docs) ? aggItem.docs : [];
kadMdFull = docs.map((d, i) => {
  const label = d.docType === 'bank' ? 'Bank-passeeropdracht'
    : d.docType === 'kadaster' ? 'Kadaster eigendomsinformatie'
    : 'Overig dossier-stuk';
  return `=== DOCUMENT ${i + 1} — ${label} — ${d.filename || `document_${i + 1}`} ===\n${d.markdown || ''}`;
}).join('\n\n');
metaForward = {
  bankDisplayName: aggItem.bankDisplayName || '',
  zaaknummer: aggItem.zaaknummer || '',
};

const kadMd = clamp(kadMdFull, MAX_MD);

const PATTERNS = [
  /\bbeslag(?:legger|gen|en)?\b/i,
  /(?:executoriaal|conservatoir)\s+beslag/i,
  /\berfpacht/i,
  /\bopstalrecht\b/i,
  /recht\s+van\s+opstal/i,
  /\bvruchtgebruik/i,
  /\bhuurbeding\b/i,
  /\bkettingbeding\b/i,
  /kwalitatieve\s+verplichting/i,
  /wet\s+voorkeursrecht/i,
  /\bWvg\b/,
  /\bvoorkeursrecht\b/i,
  /\bexploitatiebijdrage\b/i,
  /\bbaatbelasting\b/i,
  /\bwegenfonds\b/i,
];

const hits = [];
for (const re of PATTERNS) {
  const m = kadMdFull.match(re);
  if (m) hits.push(m[0]);
}
const signalCount = hits.length;

let chatInput;
if (signalCount > 0) {
  chatInput = tmpl.split('{{kadaster_markdown}}').join(kadMd);
} else {
  chatInput = 'Het bijgevoegde kadasterfragment bevat geen indicaties van beslagen, erfpacht, opstal, vruchtgebruik, huurbeding, kettingbeding, kwalitatieve verplichtingen of voorkeursrechten. Geef ALLEEN deze JSON terug, niets anders:\n{"aandachtspunten": []}';
}

return {
  json: {
    chatInput,
    signal_count: signalCount,
    signal_hits: hits.slice(0, 5),
    mode,
    ...metaForward,
  }
};

// Parseert de output van de Lasten-en-beperkingen-specialist. Werkt zowel
// met geldige JSON via format=json als met tekst inclusief markdown-fences.
// Forceert categorie='Lasten en beperkingen' en bronnen=['kadaster'].
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) {
    t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  }
  return t.trim();
}
function parseSpec(node) {
  const raw = extractText(node).trim();
  if (raw) {
    try { return JSON.parse(unwrapJsonLike(raw)); } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) {
      try { return JSON.parse(m[0]); } catch {}
    }
  }
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys(node || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = node[k];
  }
  return obj;
}

