// Object&partijen-specialist (mode=analyse). Combineert een deterministische
// ruggengraat met LLM-nuance:
//   - deterministische mismatch-checks op de structured extractie
//     (Parse Partijen Extractie): klantentelling, achternaam per positie,
//     onderpand-woonplaats vs. kadastrale gemeente — altijd gerapporteerd;
//   - een LLM-beoordeling over de ruwe markdown voor nuance (verkeerd object,
//     spellingsvarianten) — alleen wanneer bank + kadaster beide aanwezig zijn.
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';

const mode = String($('Split Input Files').first()?.json?.mode || '').trim().toLowerCase();

let registry;
try { registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8')); }
catch (err) { throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`); }
const tmpl = String(registry.legal_specialist_prompts?.object_partijen || '');
if (!tmpl) throw new Error('registry.json mist legal_specialist_prompts.object_partijen.');

const limits = registry.context_limits || {};
function clamp(s, max) { const t = String(s || ''); return t.length <= max ? t : t.slice(0, max) + '\n…[afgekapt voor partijen-prompt]'; }
const MAX_BANK = Number(limits.specialist_partijen_bank) || 10000;
const MAX_KAD = Number(limits.specialist_partijen_kadaster) || 14000;

const agg = $('Aggregate Markdowns').first()?.json || {};
const docs = Array.isArray(agg.docs) ? agg.docs : [];
const bankMdFull = docs.filter((d) => d.docType === 'bank').map((d) => d.markdown || '').join('\n\n');
const kadMdFull = docs.filter((d) => d.docType === 'kadaster').map((d) => d.markdown || '').join('\n\n');

let extracted = {};
try { extracted = $('Parse Partijen Extractie').first()?.json?.partijen_extracted || {}; } catch (_) {}
const bankKlanten = Array.isArray(extracted.bank_klanten) ? extracted.bank_klanten : [];
const kadKlanten = Array.isArray(extracted.kadaster_klanten) ? extracted.kadaster_klanten : [];

// --- deterministische checks (overgenomen uit Deterministic Checks, akte-flow) ---
function stripAccents(s) { return String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, ''); }
function normName(s) { return stripAccents(s).toLowerCase().replace(/[^a-z]/g, ''); }
function normWord(s) { return stripAccents(s).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function lastSurnameToken(s) {
  const cleaned = String(s || '').replace(/[,.;]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!cleaned) return '';
  const parts = cleaned.split(' ').filter(Boolean);
  return normName(parts[parts.length - 1] || '');
}

const detFindings = [];
if (bankKlanten.length > 0 && kadKlanten.length > 0 && bankKlanten.length !== kadKlanten.length) {
  detFindings.push({
    id: 'partijen-klantentelling-mismatch', ernst: 'kritiek', categorie: 'Object en partijen',
    titel: 'Aantal cliënten wijkt af van aantal rechthebbenden',
