const kadGem = normWord(extracted.kadastrale_gemeente);
if (bankWoon && kadGem && bankWoon !== kadGem && !bankWoon.includes(kadGem) && !kadGem.includes(bankWoon)) {
  detFindings.push({
    id: 'partijen-onderpand-gemeente-mismatch', ernst: 'aandacht', categorie: 'Object en partijen',
    titel: 'Onderpand-woonplaats wijkt af van kadastrale gemeente',
    constatering: `Passeeropdracht onderpand-woonplaats: "${extracted.onderpand_woonplaats || ''}". Kadastrale gemeente: "${extracted.kadastrale_gemeente || ''}".`,
    juridisch_kader: 'Het onderpand in de akte moet ondubbelzinnig het kadastrale perceel zijn. Verschil kan duiden op gemeentelijke herindeling — of een verkeerd perceel.',
    actie: 'Verifieer of woonplaats en kadastrale gemeente hetzelfde perceel betreffen (herindeling toegestaan; verkeerd perceel niet).',
    bronnen: ['passeeropdracht', 'kadaster']
  });
