}

return {
  json: {
    chatInput,
    signal_count: signalCount,
    det_findings: detFindings,
    bank_klanten_count: bankKlanten.length,
    kadaster_klanten_count: kadKlanten.length,
    mode,
    bankDisplayName: agg.bankDisplayName || '',
    zaaknummer: agg.zaaknummer || '',
  }
};

// Parseert de LLM-output van de Object&partijen-specialist en voegt die samen
// met de deterministische bevindingen (det_findings uit Build Partijen Prompt).
// De deterministische bevindingen verschijnen ALTIJD (harde feiten); de
// LLM-bevindingen alleen wanneer de LLM draaide. Per onderwerp wint de
// deterministische bevinding, zodat er geen dubbele aandachtspunten ontstaan.
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  return t.trim();
}
function parseSpec(node) {
  const raw = extractText(node).trim();
  if (raw) {
    try { return JSON.parse(unwrapJsonLike(raw)); } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch {} }
  }
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys(node || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = node[k];
  }
  return obj;
}
function normaliseBronnen(bron) {
  const ALLOWED = new Set(['passeeropdracht', 'kadaster']);
  const ALIASES = { eigendom: 'kadaster', eigendomsinformatie: 'kadaster', kadaster: 'kadaster', passeeropdracht: 'passeeropdracht', hypotheekopdracht: 'passeeropdracht', bank: 'passeeropdracht' };
  if (!Array.isArray(bron)) return ['passeeropdracht'];
  const out = [];
  for (const b of bron) {
    const k = String(b).toLowerCase().trim().replace(/\s+/g, '');
    const mapped = ALIASES[k] || (ALLOWED.has(k) ? k : null);
    if (mapped && !out.includes(mapped)) out.push(mapped);
  }
  return out.length ? out : ['passeeropdracht'];
}
// Grof onderwerp-label om deterministische en LLM-bevindingen over hetzelfde
// thema te ontdubbelen (deterministisch wint).
function topicKey(ap) {
  const s = `${ap?.id || ''} ${ap?.titel || ''} ${ap?.constatering || ''}`.toLowerCase();
  if (/aantal|telling|rechthebbende.*(schuldena|cli[eë]nt)|(schuldena|cli[eë]nt).*rechthebbende/.test(s)) return 'aantal';
  if (/achternaam|naamsverschil|naam.*(verschil|wijk|niet overeen)|(verschil|wijk).*naam/.test(s)) return 'naam';
  if (/gemeente|woonplaats|perceel|kadastrale aanduiding|verkeerd object|ander object|sectie|onderpand/.test(s)) return 'object';
  return `uniq:${ap?.id || Math.random()}`;
}

const node = $input.all()[0]?.json || {};

let det = [];
let signalCount = 0;
try {
  const bp = $('Build Partijen Prompt').first()?.json;
  if (Array.isArray(bp?.det_findings)) det = bp.det_findings;
  if (typeof bp?.signal_count === 'number') signalCount = bp.signal_count;
} catch (_) {}

let llm = [];
if (signalCount > 0) {
  let parsed = parseSpec(node);
  if (!parsed || typeof parsed !== 'object') parsed = { aandachtspunten: [] };
  const WRAPPER_KEYS = new Set(['analyse', 'analysis', 'data', 'response', 'result', 'output', 'object_partijen', 'partijen']);
  let depth = 0;
  while (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && Object.keys(parsed).length === 1 && WRAPPER_KEYS.has(Object.keys(parsed)[0]) && depth < 3) {
    parsed = parsed[Object.keys(parsed)[0]];
    depth++;
  }
  const aandacht = Array.isArray(parsed.aandachtspunten) ? parsed.aandachtspunten : [];
  const ALLOWED = new Set(['kritiek', 'aandacht', 'info']);
  const ALIASES = { critical: 'kritiek', blokkerend: 'kritiek', warning: 'aandacht', warn: 'aandacht', notice: 'info', informatief: 'info' };
  llm = aandacht.slice(0, 4).map((ap, i) => {
    const e = String(ap?.ernst || '').trim().toLowerCase();
    const ernst = ALLOWED.has(e) ? e : (ALIASES[e] || 'aandacht');
    const idRaw = String(ap?.id || '').trim();
    const id = idRaw ? (idRaw.startsWith('partijen-') ? idRaw : `partijen-${idRaw}`) : `partijen-llm-${i + 1}`;
    return {
      id, ernst, categorie: 'Object en partijen',
      titel: String(ap?.titel || '').slice(0, 160),
      constatering: String(ap?.constatering || ''),
      juridisch_kader: String(ap?.juridisch_kader || ''),
      actie: String(ap?.actie || ''),
      bronnen: normaliseBronnen(ap?.bronnen)
    };
  });
}

// Merge: deterministisch eerst (wint per onderwerp), dan LLM. Dedupe op
// onderwerp-label én op id.
const seenTopic = new Set();
const seenId = new Set();
const merged = [];
for (const ap of [...det, ...llm]) {
  const id = String(ap?.id || '').trim();
  if (id && seenId.has(id)) continue;
  const tk = topicKey(ap);
  if (seenTopic.has(tk)) continue;
  if (id) seenId.add(id);
  seenTopic.add(tk);
  merged.push(ap);
}

return [{ json: { partijen_aandachtspunten: merged, signal_count: signalCount, deterministic_count: det.length } }];

// Aggregates results from the 4 parallel specialist agents into a single
// 'message to a node' payload. Each agent reports: did the LLM run, did it
// find anything, how many aandachtspunten, and the raw findings array.
// Downstream (Specialist Route → Build Analysis Prompt / Build Flex Analysis
// Prompt) reads the actual aandachtspunten via cross-node refs to the
// existing Parse * JSON nodes.
function reportFor(name, prefix, parseNodeName) {
  let data;
  try { data = $(parseNodeName).first()?.json || {}; }
  catch (_) { data = {}; }
  const findings = Array.isArray(data[`${prefix}_aandachtspunten`])
    ? data[`${prefix}_aandachtspunten`]
    : [];
  const signal = typeof data.signal_count === 'number' ? data.signal_count : null;
  return {
    name,
    found: findings.length > 0,
    count: findings.length,
    signal_count: signal,
    ran_llm: signal === null ? null : signal > 0,
  };
}

const vererving = reportFor('vererving', 'vererving', 'Parse Vererving JSON');
const lasten = reportFor('lasten', 'lasten', 'Parse Lasten JSON');
const burgerlijke = reportFor('burgerlijke', 'burgerlijke', 'Parse Burgerlijke JSON');
const partijen = reportFor('partijen', 'partijen', 'Parse Partijen JSON');

const reports = [vererving, lasten, burgerlijke, partijen];
const totalFindings = reports.reduce((sum, r) => sum + r.count, 0);
const ranLlmCount = reports.filter((r) => r.ran_llm === true).length;

return [{
  json: {
    specialists: { vererving, lasten, burgerlijke, partijen },
    summary: {
      total_findings: totalFindings,
      specialists_with_findings: reports.filter((r) => r.found).length,
      llm_calls_made: ranLlmCount,
      llm_calls_skipped: reports.length - ranLlmCount,
    },
  },
}];

// Bouwt de prompt voor de flex-analyse. Sinds de specialist-splitsing doet deze
// chain alleen nog: (1) de feitelijke dossier-samenvatting en (2) de categorieen
// Bedragen en Documentatie. Vererving, lasten, burgerlijke staat en object&partijen
// zijn al door de vier specialisten beoordeeld; hun volledige documentteksten hoeven
// hier dus niet nogmaals mee. Per document gaat alleen de kop mee (passeeropdracht
// ruim, rest kort): met volledige stukken liep de prompt bij 7 documenten op tot
// ~29k tekens (~7300 tokens), waardoor numCtx 8192 overliep en de generatie 20+
// minuten door-maalde (executie 226). Budget ver onder het venster houden is de
// snelheidsfix; de limieten staan centraal in registry.context_limits.
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';

let input = $json || {};
if (!Array.isArray(input.docs) || input.docs.length === 0) {
  try {
    const agg = $('Aggregate Markdowns').first()?.json;
    if (agg && Array.isArray(agg.docs) && agg.docs.length > 0) input = agg;
  } catch (_) {}
}
const docs = Array.isArray(input.docs) ? input.docs : [];

let registry;
try {
  registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
} catch (err) {
  throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`);
}

const basePrompt = String(registry.flex_analysis_prompt || registry.legal_analysis_prompt || '');
if (!basePrompt) {
  throw new Error('registry.json mist flex_analysis_prompt.');
}

const limits = registry.context_limits || {};
const MAX_BANK   = Number(limits.flex_bank_per_doc)   || 4000;
const MAX_OVERIG = Number(limits.flex_overig_per_doc) || 1200;
const MAX_TOTAL  = Number(limits.flex_combined)       || 8000;

function clamp(s, max) {
  const txt = String(s || '');
  if (txt.length <= max) return txt;
  return txt.slice(0, max) + '\n…[fragment afgekapt; alleen documentkop opgenomen]';
}

function docTypeLabel(t) {
  if (t === 'bank') return 'Bank-passeeropdracht';
  if (t === 'kadaster') return 'Kadaster eigendomsinformatie';
  return 'Aanvullend dossierstuk';
}

// Bank eerst: als het totaalbudget alsnog knijpt, overleven de leninggegevens.
const ordered = [
  ...docs.filter(d => d.docType === 'bank'),
  ...docs.filter(d => d.docType === 'kadaster'),
  ...docs.filter(d => d.docType !== 'bank' && d.docType !== 'kadaster'),
];

const blocks = ordered.map((d, i) => {
  const max = d.docType === 'bank' ? MAX_BANK : MAX_OVERIG;
  return `=== DOCUMENT ${i + 1} — ${docTypeLabel(d.docType)} — ${d.filename} ===\n${clamp(d.markdown, max)}`;
}).join('\n\n');

// Zonder passeeropdracht expliciet zeggen dat bank/bedragen/looptijd onbekend
// zijn; anders verzint het model ze (zie hallucinatie-fix van 14-07).
const geenBankNote = ordered.some(d => d.docType === 'bank')
  ? ''
  : 'LET OP: in dit dossier is GEEN passeeropdracht aangeleverd. Er is dus geen bank, '
    + 'geen hypotheekbedrag en geen looptijd bekend. Noem deze niet; benoem ze als niet aangeleverd.\n\n';

// {{bank_markdown}} is de enige placeholder in flex_analysis_prompt; de andere twee
// joins zijn een vangnet voor als ooit op legal_analysis_prompt wordt teruggevallen.
const chatInput = basePrompt
  .split('{{bank_markdown}}').join(clamp(geenBankNote + blocks, MAX_TOTAL))
  .split('{{kadaster_markdown}}').join('(zie documentfragmenten hierboven)')
  .split('{{extracted_json}}').join('(geen gestructureerde extractie in deze analyse-only-flow)');

return [{
  json: {
    chatInput,
    mode: 'analyse',
    zaaknummer: input.zaaknummer,
    bankDisplayName: input.bankDisplayName,
    klantSamenvatting: input.klantSamenvatting || '',
    documentCount: docs.length
  }
}];

// Parseert de juridische analyse JSON die de LLM teruggeeft (mode=analyse).
// Mega-prompt output wordt gecombineerd met de vier specialist-bevindingen
// (Vererving, Lasten, Burgerlijke, Object&partijen). Specialist-bevindingen krijgen voorrang in hun eigen
// categorie; mega-prompt mag alleen in een specialist-categorie blijven als
// die specialist niets gevonden heeft.
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) {
    t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  }
  return t.trim();
}
function parseAnalysis(jsonNode) {
  const raw = extractText(jsonNode).trim();
  if (raw) {
    try { const _p = JSON.parse(unwrapJsonLike(raw)); if (!Array.isArray(_p)) return _p; } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) {
      try { return JSON.parse(m[0]); } catch {}
    }
  }
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys(jsonNode || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = jsonNode[k];
  }
  if ('aandachtspunten' in obj || 'samenvatting' in obj) return obj;
  return null;
}

const all = $input.all();
const node = all[0]?.json || {};
let parsed = parseAnalysis(node);

if (!parsed || typeof parsed !== 'object') {
  parsed = { samenvatting: '', aandachtspunten: [] };
}

const WRAPPER_KEYS = new Set(['analyse', 'analysis', 'data', 'response', 'result', 'output']);
let depth = 0;
while (
  parsed && typeof parsed === 'object' && !Array.isArray(parsed) &&
  Object.keys(parsed).length === 1 &&
  WRAPPER_KEYS.has(Object.keys(parsed)[0]) && depth < 3
) {
  parsed = parsed[Object.keys(parsed)[0]];
  depth++;
}

const aandacht = Array.isArray(parsed.aandachtspunten) ? parsed.aandachtspunten : [];
const ALLOWED = new Set(['kritiek', 'aandacht', 'info']);
const ALIASES = { critical: 'kritiek', blokkerend: 'kritiek', warning: 'aandacht', warn: 'aandacht', notice: 'info', informatief: 'info' };
const normalised = aandacht.map((ap, i) => {
  const e = String(ap?.ernst || '').trim().toLowerCase();
  const ernst = ALLOWED.has(e) ? e : (ALIASES[e] || 'info');
  return {
    id: String(ap?.id || `punt-${i + 1}`),
    ernst,
    categorie: String(ap?.categorie || 'Overig'),
    titel: String(ap?.titel || '').slice(0, 160),
    constatering: String(ap?.constatering || ''),
    juridisch_kader: String(ap?.juridisch_kader || ''),
    actie: String(ap?.actie || ''),
    bronnen: Array.isArray(ap?.bronnen) ? ap.bronnen.map(String) : []
  };
});

const samenvatting = String(parsed.samenvatting || '').trim();

// Haal de drie specialist-bevindingen op (Parse * Analyse JSON zit elk in
// de directe voorouder-chain, dus $() is hier betrouwbaar).
let verervingItems = [];
let lastenItems = [];
let burgerlijkeItems = [];
let partijenItems = [];
try {
  const v = $('Parse Vererving JSON').first()?.json;
  if (Array.isArray(v?.vererving_aandachtspunten)) verervingItems = v.vererving_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] vererving merge:', e?.message); }
try {
  const l = $('Parse Lasten JSON').first()?.json;
  if (Array.isArray(l?.lasten_aandachtspunten)) lastenItems = l.lasten_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] lasten merge:', e?.message); }
try {
  const b = $('Parse Burgerlijke JSON').first()?.json;
  if (Array.isArray(b?.burgerlijke_aandachtspunten)) burgerlijkeItems = b.burgerlijke_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] burgerlijke merge:', e?.message); }
try {
  const p = $('Parse Partijen JSON').first()?.json;
  if (Array.isArray(p?.partijen_aandachtspunten)) partijenItems = p.partijen_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] partijen merge:', e?.message); }

// Filter mega-prompt items in de vier specialist-categorieën. Specialist
// heeft voorrang; alleen als de specialist 0 items teruggaf mag mega-prompt
// die categorie nog vullen.
const RESERVED = {
  'vererving': verervingItems,
  'lasten en beperkingen': lastenItems,
  'burgerlijke staat': burgerlijkeItems,
  'object en partijen': partijenItems,
};
const filteredNorm = normalised.filter((ap) => {
  const cat = String(ap?.categorie || '').toLowerCase();
  const owner = RESERVED[cat];
  if (!owner) return true;
  return owner.length === 0;
});

const seenM = new Set();
const merged = [];
for (const ap of [...verervingItems, ...lastenItems, ...burgerlijkeItems, ...partijenItems, ...filteredNorm]) {
  const id = String(ap?.id || '').trim();
  if (id && seenM.has(id)) continue;
  if (id) seenM.add(id);
  merged.push(ap);
}
const ORDER_M = { kritiek: 0, aandacht: 1, info: 2 };
merged.sort((a, b) => (ORDER_M[a.ernst] ?? 9) - (ORDER_M[b.ernst] ?? 9));

// Deterministische, gegarandeerd consistente samenvatting-aanvulling. De LLM
// beschrijft het dossier feitelijk (zonder oordeel over aandachtspunten); de
// telling hieronder komt uit de daadwerkelijk samengevoegde bevindingen, zodat
// de samenvatting die nooit meer tegenspreekt (fix observatie 2).
const kritiekCount = merged.filter((x) => x.ernst === 'kritiek').length;
const aandachtCount = merged.filter((x) => x.ernst === 'aandacht').length;
const infoCount = merged.filter((x) => x.ernst === 'info').length;

const delen = [];
if (kritiekCount) delen.push(`${kritiekCount}\u00d7 kritiek`);
if (aandachtCount) delen.push(`${aandachtCount}\u00d7 aandacht`);
if (infoCount) delen.push(`${infoCount}\u00d7 info`);

let bevindingenZin;
if (delen.length === 0) {
  bevindingenZin = 'De analyse signaleert geen bijzondere juridische aandachtspunten.';
} else {
  bevindingenZin = `De analyse signaleert ${merged.length} aandachtspunt${merged.length === 1 ? '' : 'en'} (${delen.join(', ')}).`;
  const kritiekTitels = merged.filter((x) => x.ernst === 'kritiek').map((x) => x.titel).filter(Boolean);
  if (kritiekTitels.length) bevindingenZin += ` Kritiek: ${kritiekTitels.join('; ')}.`;
}

const finalSamenvatting = [samenvatting, bevindingenZin].filter(Boolean).join(' ').trim();

return [{
  json: {
    analysis: {
      samenvatting: finalSamenvatting,
      aandachtspunten: merged
    },
    counts: {
      kritiek: kritiekCount,
      aandacht: aandachtCount,
      info: infoCount,
      totaal: merged.length,
      specialisten: {
        vererving: verervingItems.length,
        lasten: lastenItems.length,
        burgerlijke: burgerlijkeItems.length,
        partijen: partijenItems.length
      }
    }
  }
}];

// Args naar tijdelijk JSON-bestand schrijven voor genereer_juridische_analyse.py
// (analyse-only flow). Python-script verwijdert het bestand na inlezen.
const fs = require('fs');
const execId = String($execution.id || 'single').replace(/[^0-9A-Za-z_-]/g, '_').slice(0, 32);
const argsFile = `/tmp/n8n_args_flex_analyse_${execId}_${Date.now()}.json`;
const meta = $('Aggregate Markdowns').first()?.json || {};
const j = $json || {};
const payload = {
  analysis: j.analysis || {},
  zaaknummer: String(meta.zaaknummer || ''),
  bank: String(meta.bankDisplayName || ''),
  klant: String(meta.klantSamenvatting || ''),
};
fs.writeFileSync(argsFile, JSON.stringify(payload), 'utf8');
return { json: { ...j, argsFile } };

// Bouwt de webhook-respons voor de analyse-only-flow.
const analysisCmdNode = $('Generate Flex Analysis DOCX').first()?.json || {};
const analysisCmdStdout = String(analysisCmdNode.stdout || '');
const analysisCmdErr = String(analysisCmdNode.stderr || '');
const analysisMatch = analysisCmdStdout.match(/SUCCESS:\s*(.+)/);
const analysisPath = analysisMatch ? analysisMatch[1].trim() : '';
const analysisFilename = analysisPath ? analysisPath.split('/').pop() : '';

const analysisDataNode = $('Parse Flex Analysis JSON').first()?.json || {};
const analysis = analysisDataNode.analysis || { samenvatting: '', aandachtspunten: [] };
const counts = analysisDataNode.counts || {
  kritiek: 0, aandacht: 0, info: 0,
  totaal: (analysis.aandachtspunten || []).length
};

const meta = $('Aggregate Markdowns').first()?.json || {};

return [{
  json: {
    success: true,
    mode: 'analyse',
    filename: null,
    file_path: null,
    download_url: null,
    bank_id: null,
    bank_display_name: meta.bankDisplayName || null,
    klant_samenvatting: meta.klantSamenvatting || '',
    zaaknummer: meta.zaaknummer || '',
    document_count: meta.documentCount || 0,
    analysis: {
      ...analysis,
      counts,
      filename: analysisFilename || null,
      file_path: analysisPath || null,
      download_url: analysisFilename ? `http://localhost:8080/output/${analysisFilename}` : null,
      generation_warning: !analysisPath
        ? `Analyse-DOCX niet gegenereerd. stdout=${analysisCmdStdout.slice(0, 200)}; stderr=${analysisCmdErr.slice(0, 200)}`
        : null
    }
  }
}];
